var views = new FilteredElementCollector(doc).OfClass(typeof(View)).Cast<View>().Where(v => !v.IsTemplate).Select(v => new { v.Name, id = v.Id.IntegerValue, type = v.ViewType.ToString(), scale = v.ViewType == ViewType.Schedule ? 0 : v.Scale }).ToList();
var tbs = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_TitleBlocks).OfClass(typeof(FamilySymbol)).Cast<FamilySymbol>().Select(s => new { fam = s.FamilyName, s.Name, id = s.Id.IntegerValue }).ToList();
var vft = new FilteredElementCollector(doc).OfClass(typeof(ViewFamilyType)).Cast<ViewFamilyType>().Where(t => t.ViewFamily == ViewFamily.Section || t.ViewFamily == ViewFamily.Elevation).Select(t => new { t.Name, fam = t.ViewFamily.ToString(), id = t.Id.IntegerValue }).ToList();
var dimTypes = new FilteredElementCollector(doc).OfClass(typeof(DimensionType)).Cast<DimensionType>().Where(d => d.StyleType == DimensionStyleType.Linear).Select(d => new { d.Name, id = d.Id.IntegerValue }).ToList();
return new { views, tbs, vft, dimTypes };
